mapper.sql:

AND r.STATUS_CODE IN ('REQ_01', 'REQ_02')


AND EXISTS (
	SELECT 1
	  FROM FIXER_CATEGORY fc
	 WHERE fc.USER_NO       = #{userNo}
	   AND fc.CATEGORY_CODE = r.CATEGORY_CODE
)


AND EXISTS (
	SELECT 1
	  FROM FIXER_REGION fr
	  JOIN COMMON_CODE  rc ON rc.CODE_ID = fr.REGION_CODE
	 WHERE fr.USER_NO = #{userNo}
	   AND r.SERVICE_ADDRESS LIKE '%' || rc.CODE_NAME || '%'
)


AND NOT EXISTS (
	SELECT 1
	  FROM FIXER_BLOCK b
	 WHERE b.FIXER_NO = #{userNo}
	   AND b.USER_NO  = r.USER_NO
)
